  'triage.hip_not_reproduces': ['Moving the hip does not bring on the knee pain → knee pathway', 'कूल्हा हिलाने से घुटने का दर्द नहीं होता → घुटने का पाथवे', 'खुबा हलवल्यावर गुडघ्याचे दुखणे येत नाही → गुडघ्याचा पाथवे'],
  'triage.low_back_moves': ['Pain changes with bending and arching the low back → low-back pathway', 'कमर झुकाने और पीछे मोड़ने से दर्द बदलता है → कमर का पाथवे', 'कंबर वाकवल्यावर आणि मागे झुकवल्यावर वेदना बदलते → कंबरेचा पाथवे'],
  'triage.neck_moves': ['Pain changes with breathing, twisting the chest, or neck and arm movement → neck & upper-back pathway', 'साँस लेने, छाती घुमाने, या गर्दन और बाँह की हरकत से दर्द बदलता है → गर्दन और ऊपरी पीठ का पाथवे', 'श्वास घेताना, छाती फिरवताना, किंवा मान व हाताच्या हालचालीने वेदना बदलते → मान व वरच्या पाठीचा पाथवे'],

  // ---- halts ----
  'halt.ESCALATED': ['Routine assessment stopped: a safety concern needs action first.', 'सामान्य जाँच रोकी गई: पहले सुरक्षा चिंता पर कार्रवाई ज़रूरी है।', 'नियमित तपासणी थांबवली: आधी सुरक्षा चिंतेवर कृती आवश्यक आहे.'],
  'halt.SWITCHED': ['The pain may be coming from another region. Continue in the linked assessment.', 'दर्द किसी दूसरे हिस्से से आ सकता है। जुड़ी हुई जाँच में जारी रखें।', 'वेदना दुसऱ्या भागातून येत असू शकते. जोडलेल्या तपासणीत पुढे चला.'],
  'halt.SWITCH_LOOP': ['This would send the patient back to a pathway already tried. A clinician must review.', 'इससे मरीज़ उसी पाथवे में लौटेंगे जो पहले आज़माया जा चुका है। चिकित्सक को समीक्षा करनी होगी।', 'यामुळे रुग्ण आधीच वापरलेल्या पाथवेमध्ये परत जाईल. चिकित्सकाने पुनरावलोकन करावे.'],
  'halt.NEEDS_REVIEW': ['This question has no clear answer, so the pathway cannot choose a branch. A clinician must review.', 'इस सवाल का स्पष्ट जवाब नहीं है, इसलिए पाथवे कोई शाखा नहीं चुन सकता। चिकित्सक को समीक्षा करनी होगी।', 'या प्रश्नाचे स्पष्ट उत्तर नाही, त्यामुळे पाथवे शाखा निवडू शकत नाही. चिकित्सकाने पुनरावलोकन करावे.'],
  'halt.EXAM_PENDING': ['A hands-on test was not performed. It is NOT treated as normal. No assessment or plan is produced until someone trained does the test or a clinician decides.', 'हाथ से की जाने वाली जाँच नहीं हुई। इसे सामान्य नहीं माना गया है। जब तक कोई प्रशिक्षित व्यक्ति जाँच न करे या चिकित्सक निर्णय न ले, कोई आकलन या योजना नहीं बनेगी।', 'हाताने करायची तपासणी झाली नाही. ती सामान्य मानलेली नाही. प्रशिक्षित व्यक्तीने तपासणी करेपर्यंत किंवा चिकित्सकाने निर्णय घेईपर्यंत कोणतेही मूल्यांकन किंवा योजना तयार होणार नाही.'],
  'halt.REOPEN_SAFETY': ['This answer points back to a safety check. Ask that check again, or send to the clinician.', 'यह जवाब एक सुरक्षा जाँच की ओर वापस इशारा करता है। वह जाँच दोबारा पूछें, या चिकित्सक को भेजें।', 'हे उत्तर एका सुरक्षा तपासणीकडे परत निर्देश करते. ती तपासणी पुन्हा विचारा किंवा चिकित्सकाकडे पाठवा.'],
  'halt.CYCLE': ['The pathway has come back to a step already done without reaching a result. A clinician must review.', 'पाथवे बिना किसी नतीजे के पहले किए गए चरण पर लौट आया है। चिकित्सक को समीक्षा करनी होगी।', 'पाथवे कोणत्याही निष्कर्षाशिवाय आधी केलेल्या टप्प्यावर परत आला आहे. चिकित्सकाने पुनरावलोकन करावे.'],
  'halt.NO_SOURCE_BRANCH': ['The source flowchart has no next step for this situation. A clinician must review.', 'मूल फ़्लोचार्ट में इस स्थिति के लिए अगला चरण नहीं है। चिकित्सक को समीक्षा करनी होगी।', 'मूळ फ्लोचार्टमध्ये या परिस्थितीसाठी पुढचा टप्पा नाही. चिकित्सकाने पुनरावलोकन करावे.'],
  'halt.REFERRAL_END': ['This path ends in a referral, not an exercise plan.', 'यह रास्ता रेफ़रल पर ख़त्म होता है, व्यायाम योजना पर नहीं।', 'हा मार्ग रेफरलवर संपतो, व्यायाम योजनेवर नाही.'],
  'halt.AGE_UNKNOWN': ['The next step depends on age, and no age is recorded.', 'अगला चरण उम्र पर निर्भर है, और उम्र दर्ज नहीं है।', 'पुढचा टप्पा वयावर अवलंबून आहे, आणि वय नोंदलेले नाही.'],
  'halt.reopen': ['Ask this check again', 'यह जाँच दोबारा पूछें', 'ही तपासणी पुन्हा विचारा'],
